package postcard

import (
	"encoding/hex"
	"math"
	"reflect"
	"testing"
)

// Golden vectors generated by the real Rust postcard crate (see /tmp/vecgen.rs,
// kept out of the repo). The murmur-shaped composites mirror src/model.rs
// field and variant order: Version, Value, Cell.

type testVersion struct {
	millis  uint64
	logical uint32
	node    []byte
}

type testValue struct {
	disc uint32 // 0 Null, 1 Integer, 2 Real, 3 Text, 4 Blob
	i    int64
	f    float64
	s    string
	b    []byte
}

type testCell struct {
	column  string
	value   testValue
	version testVersion
}

type testEnum struct {
	disc uint32 // 0 A, 1 B(u32), 2 C{x:u8}
	u    uint32
	x    uint8
}

type testPair struct {
	k string
	v uint32
}

type vecCase struct {
	name string
	hex  string
	enc  func(e *Encoder)
	dec  func(d *Decoder) any
	want any
}

func u8v(v uint8) func(*Encoder)    { return func(e *Encoder) { e.U8(v) } }
func u16v(v uint16) func(*Encoder)  { return func(e *Encoder) { e.U16(v) } }
func u32v(v uint32) func(*Encoder)  { return func(e *Encoder) { e.U32(v) } }
func u64v(v uint64) func(*Encoder)  { return func(e *Encoder) { e.U64(v) } }
func i8v(v int8) func(*Encoder)     { return func(e *Encoder) { e.I8(v) } }
func i16v(v int16) func(*Encoder)   { return func(e *Encoder) { e.I16(v) } }
func i32v(v int32) func(*Encoder)   { return func(e *Encoder) { e.I32(v) } }
func i64v(v int64) func(*Encoder)   { return func(e *Encoder) { e.I64(v) } }
func boolv(v bool) func(*Encoder)   { return func(e *Encoder) { e.Bool(v) } }
func f32v(v float32) func(*Encoder) { return func(e *Encoder) { e.F32(v) } }
func f64v(v float64) func(*Encoder) { return func(e *Encoder) { e.F64(v) } }
func strv(v string) func(*Encoder)  { return func(e *Encoder) { e.String(v) } }
func bytesv(v []byte) func(*Encoder) {
	return func(e *Encoder) { e.ByteString(v) }
}

func du8(d *Decoder) any   { return d.U8() }
func du16(d *Decoder) any  { return d.U16() }
func du32(d *Decoder) any  { return d.U32() }
func du64(d *Decoder) any  { return d.U64() }
func di8(d *Decoder) any   { return d.I8() }
func di16(d *Decoder) any  { return d.I16() }
func di32(d *Decoder) any  { return d.I32() }
func di64(d *Decoder) any  { return d.I64() }
func dbool(d *Decoder) any { return d.Bool() }
func df32(d *Decoder) any  { return d.F32() }
func df64(d *Decoder) any  { return d.F64() }
func dstr(d *Decoder) any  { return d.String() }
func dbytes(d *Decoder) any {
	b := d.Bytes()
	if d.Err() != nil {
		return []byte(nil)
	}
	out := make([]byte, len(b))
	copy(out, b)
	return out
}

