type testDur struct {
	secs  uint64
	nanos uint32
}

func (p testPair) with(secs uint64, nanos uint32) any {
	return testDur{secs: secs, nanos: nanos}
}

func decodeHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad vector hex %q: %v", s, err)
	}
	return b
}

func TestVectorsEncode(t *testing.T) {
	for _, v := range vectors {
		t.Run(v.name, func(t *testing.T) {
			e := NewEncoder(64)
			v.enc(e)
			if got := hex.EncodeToString(e.Bytes()); got != v.hex {
				t.Fatalf("encode = %s, want %s", got, v.hex)
			}
		})
	}
}

func TestVectorsDecode(t *testing.T) {
	for _, v := range vectors {
		t.Run(v.name, func(t *testing.T) {
			d := NewDecoder(decodeHex(t, v.hex))
			got := v.dec(d)
			if err := d.End(); err != nil {
				t.Fatalf("decode error: %v", err)
			}
			if !reflect.DeepEqual(got, v.want) {
				t.Fatalf("decode = %#v, want %#v", got, v.want)
			}
		})
	}
}

// Every proper prefix of every vector must fail: values are self-framing,
// so truncation can never yield a different valid value.
func TestVectorsTruncation(t *testing.T) {
	for _, v := range vectors {
		t.Run(v.name, func(t *testing.T) {
			raw := decodeHex(t, v.hex)
			for i := range len(raw) {
				d := NewDecoder(raw[:i])
				v.dec(d)
				if err := d.End(); err == nil {
					t.Fatalf("prefix len %d of %d decoded without error", i, len(raw))
				}
			}
		})
	}
}

func TestDecodeErrors(t *testing.T) {
	cases := []struct {
		name string
		hex  string
		dec  func(d *Decoder)
	}{
		{"varint_overflow_u64", "ffffffffffffffffff03", func(d *Decoder) { d.U64() }},
		{"varint_continuation_end", "ffffffffffffffffff7f", func(d *Decoder) { d.U64() }},
		{"u16_overflow", "ffffffff0f", func(d *Decoder) { d.U16() }},
		{"u32_overflow", "ffffffffffff01", func(d *Decoder) { d.U32() }},
		{"i32_overflow", "feffffff0f", func(d *Decoder) { d.I16() }},
		{"bool_tag_2", "02", func(d *Decoder) { d.Bool() }},
		{"bool_tag_ff", "ff", func(d *Decoder) { d.Bool() }},
		{"bad_utf8", "01ff", func(d *Decoder) { _ = d.String() }},
		{"truncated_utf8", "02c3", func(d *Decoder) { _ = d.String() }},
		{"len_huge", "ffffffffffffffffff01", func(d *Decoder) { d.Bytes() }},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			d := NewDecoder(decodeHex(t, c.hex))
			c.dec(d)
			if err := d.Err(); err == nil {
				t.Fatalf("expected error, got value with %d bytes left", d.Remaining())
			}
		})
	}
}

func TestTrailingBytes(t *testing.T) {
	d := NewDecoder([]byte{0x01, 0x00})
	d.U32()
	if err := d.End(); err != ErrTrailing {
		t.Fatalf("End = %v, want ErrTrailing", err)
	}
}

func TestRoundTripInts(t *testing.T) {
	u64s := []uint64{0, 1, 127, 128, 255, 256, 300, 16383, 16384, 1 << 28, 1 << 32, math.MaxUint32, math.MaxUint64}
	for _, v := range u64s {
		e := NewEncoder(16)
		e.U64(v)
		d := NewDecoder(e.Bytes())
		if got := d.U64(); got != v || d.End() != nil {
			t.Fatalf("u64 %d round trip = %d, %v", v, got, d.Err())
		}
	}
	i64s := []int64{0, 1, -1, 63, -64, 300, -300, math.MaxInt32, math.MinInt32, math.MaxInt64, math.MinInt64}
	for _, v := range i64s {
		e := NewEncoder(16)
		e.I64(v)
		d := NewDecoder(e.Bytes())
		if got := d.I64(); got != v || d.End() != nil {
			t.Fatalf("i64 %d round trip = %d, %v", v, got, d.Err())
		}
	}
}
